// TestLiveAPI checks the client against the real Personal API (read-only:
// lists recent activities and downloads one). It needs a key file:
//
//	MYVELO_GARMIN_KEY_FILE=~/.config/garmin-personal-api-key go test -run TestLiveAPI -v ./internal/garmin
func TestLiveAPI(t *testing.T) {
	path := os.Getenv("MYVELO_GARMIN_KEY_FILE")
	if path == "" {
		t.Skip("set MYVELO_GARMIN_KEY_FILE to run against the real Garmin API")
	}
	key, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	c := NewClient(strings.TrimSpace(string(key)), nil)
	ctx := context.Background()
	since := time.Now().AddDate(0, 0, -10)
	list, err := c.Activities(ctx, since)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("%d activities since %s; token valid until %s", len(list), since.Format(time.DateOnly), c.expires.Format(time.RFC3339))
	for _, a := range list {
		t.Logf("  %d %s %q type=%s device=%d", a.ID, a.StartTimeGMT, a.Name, a.ActivityType.TypeKey, a.DeviceID)
	}
	if len(list) == 0 {
		return
	}
	data, err := c.DownloadFIT(ctx, list[0].ID)
	if err != nil {
		t.Fatal(err)
	}
	s, err := fitfile.Parse(bytes.NewReader(data))
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("download %d: %d bytes FIT, key %s, %s/%s %.1f km", list[0].ID, len(data), s.Key, s.Sport, s.SubSport, s.DistanceM/1000)
}
